pecas.css:
.nexus-hero-strip {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  background: var(--nexus-light);
  border: 1px solid rgba(0,0,0,0.06);
  border-radius: 50rem;
  padding: 10px 22px;
  margin: 0 auto 1.5rem;
  max-width: fit-content;
}
.nexus-hero-strip-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: var(--nexus-primary);
  flex-shrink: 0;
}
.nexus-hero-strip p {
  margin: 0;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--nexus-dark);
}

cssVariantes:
.nexus-hero-strip {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  background: var(--nexus-light);
  border: 1px solid rgba(0,0,0,0.06);
  border-radius: 50rem;
  padding: 10px 22px;
  margin: 0 auto 1.5rem;
  max-width: fit-content;
}
.nexus-hero-strip-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: var(--nexus-primary);
  flex-shrink: 0;
}
.nexus-hero-strip p {
  margin: 0;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--nexus-dark);
}

.nexus-hero-strip--bar {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  width: 100%;
  background: transparent;
  border: 1px solid var(--nexus-primary);
  border-radius: 8px;
  padding: 10px 22px;
  margin: 0 auto 1.5rem;
  max-width: 640px;
}
.nexus-hero-strip-icon { color: var(--nexus-primary); font-size: 0.7rem; flex-shrink: 0; }
.nexus-hero-strip--bar p { margin: 0; font-size: 0.9rem; font-weight: 600; color: var(--nexus-dark); }

.nexus-hero-strip--gradient {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  background: linear-gradient(135deg, var(--nexus-primary), #6366f1);
  border: none;
  border-radius: 50rem;
  padding: 10px 24px;
  margin: 0 auto 1.5rem;
  max-width: fit-content;
}
.nexus-hero-strip--gradient .nexus-hero-strip-dot { width: 8px; height: 8px; border-radius: 50%; background: #fff; flex-shrink: 0; }
.nexus-hero-strip--gradient p { margin: 0; font-size: 0.9rem; font-weight: 600; color: #fff; }

.nexus-hero-strip--ticker {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: transparent;
  border: none;
  border-bottom: 1px solid var(--nexus-primary);
  padding: 6px 4px 10px;
  margin: 0 auto 1.5rem;
  max-width: fit-content;
}
.nexus-hero-strip-arrow { color: var(--nexus-primary); font-weight: 700; font-size: 0.85rem; }
.nexus-hero-strip--ticker p { margin: 0; font-size: 0.9rem; font-weight: 600; color: var(--nexus-dark); }

.nexus-hero-strip--badge {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  background: var(--nexus-light);
  border: 1px solid rgba(0,0,0,0.06);
  border-radius: 50rem;
  padding: 6px 22px 6px 6px;
  margin: 0 auto 1.5rem;
  max-width: fit-content;
}
.nexus-hero-strip--badge .nexus-hero-strip-dot {
  width: 26px; height: 26px;
  border-radius: 50%;
  background: var(--nexus-primary);
  flex-shrink: 0;
}
.nexus-hero-strip--badge p { margin: 0; font-size: 0.9rem; font-weight: 600; color: var(--nexus-dark); }
